        string s(n, '0');
        for (int i = 0; i < n; ++i) {
            if (s[i] != target[i]) {
                ++ops;
                for (int j = i; j < n; ++j) s[j] = (s[j] == '0') ? '1' : '0';
            }
        }
        return ops;
    }
};

