class Solution {
    public int minFlips(String target) {
        int n = target.length(), ops = 0;
        char[] s = new char[n];
        Arrays.fill(s, '0');
        for (int i = 0; i < n; i++) {
            if (s[i] != target.charAt(i)) {
                ops++;
                for (int j = i; j < n; j++) s[j] = (s[j] == '0') ? '1' : '0';
            }
        }
        return ops;
    }
}

