class Solution {
public:
    int minFlips(string target) {
        int ops = 0, flipped = 0;
        for (char c : target) {
            int bit = c - '0';
            if ((bit ^ flipped) != 0) {
                ++ops;
                flipped ^= 1;
            }
        }
        return ops;
    }
};

